return {
    shallowEqual = function(p1, p2) -- shallowEqual | line: 10
        if p1 == p2 then
            return true
        end

        if p1 == nil or p2 == nil then
            return false
        end

        for v1, v2 in pairs(p1) do
            if p2[v1] ~= v2 then
                return false
            end
        end

        for v3, v4 in pairs(p2) do
            if p1[v3] ~= v4 then
                return false
            end
        end

        return true
    end
}
